import os
import sys
import stat
from pathlib import Path

CODEWARDEN_ROOT = Path(__file__).resolve().parent.parent
PYTHON_BIN = sys.executable

HOOK_TEMPLATE = f"""#!/usr/bin/env bash
# Auto-generated by CodeWarden — Local Offline Pre-Commit Security Gate
echo "🛡️  Running CodeWarden Pre-Commit Security Audit on staged diff..."
PYTHONPATH="{CODEWARDEN_ROOT}" "{PYTHON_BIN}" -m app.cli diff --repo "$(git rev-parse --show-toplevel)" --staged --fail-on CRITICAL HIGH
STATUS=$?
if [ $STATUS -ne 0 ]; then
    echo "❌ Commit blocked by CodeWarden due to HIGH/CRITICAL security findings."
    exit 1
fi
echo "✅ CodeWarden audit passed."
exit 0
"""


def main():
    target_repo = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd()
    hooks_dir = target_repo / ".git" / "hooks"
    if not hooks_dir.exists():
        print(f"Error: {target_repo} is not a Git repository (.git/hooks not found).")
        sys.exit(1)

    hook_path = hooks_dir / "pre-commit"
    hook_path.write_text(HOOK_TEMPLATE, encoding="utf-8")
    hook_path.chmod(hook_path.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    print(f"Installed CodeWarden pre-commit hook at: {hook_path}")


if __name__ == "__main__":
    main()
